class Solution {
public:
    int maxFreeTime(int eventTime, vector<int>& startTime, vector<int>& endTime) {
        int n = startTime.size();
        long long v[3] = {-1, -1, -1};
        int idx[3] = {-1, -1, -1};

        auto add = [&](long long val, int i) {
            for (int k = 0; k < 3; ++k) {
                if (val > v[k]) {
                    for (int j = 2; j > k; --j) { v[j] = v[j-1]; idx[j] = idx[j-1]; }
                    v[k] = val; idx[k] = i;
                    break;
                }
            }
        };

        auto gap = [&](int i) -> long long {
            long long l = (i == 0) ? 0 : endTime[i-1];
            long long r = (i == n) ? eventTime : startTime[i];
            return r - l;
        };

        for (int i = 0; i <= n; ++i) add(gap(i), i);

        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            long long left = gap(i), right = gap(i+1);
            long long dur = (long long)endTime[i] - startTime[i];
            long long best = 0;
            for (int k = 0; k < 3; ++k)
                if (idx[k] != i && idx[k] != i+1 && v[k] >= dur)
                    best = max(best, v[k]);
            long long cand = left + right + (best >= dur ? dur : 0);
            ans = max(ans, cand);
        }
        return (int)ans;
    }
};
